template <typename T>
class DequeStackAdapter {
private:
    std::deque<T> container_; // The Adaptee

public:
    void push(const T& val) { container_.push_back(val); }
    void pop() { container_.pop_back(); }
    T& top() { return container_.back(); }
    bool empty() const { return container_.empty(); }
};

// Use: DequeStackAdapter<int> s; s.push(42); s.pop();
